      (have app {a b c d : List Expression.Ident} (h : a.Subset c) (h' : b.Subset d) : (a ++ b).Subset (c ++ d) :=
        fun _ hm => List.mem_append.mpr ((List.mem_append.mp hm).imp (@h _) (@h' _));
